namespace Atc.Rest.Api.Generator.Tests.Helpers;

public class GeneratedCodeAttributeHelperTests
{
    // Normalized to \n regardless of this file's own line endings, so the \n-joined
    // substring assertions below are stable no matter how the file is checked out.
    private static readonly string SampleContent = """
        // <auto-generated />
        #nullable enable

        using System.CodeDom.Compiler;
        using Microsoft.Extensions.DependencyInjection;

        namespace PetStoreSimple;

        /// <summary>
        /// Extension methods for registering API handlers in the dependency injection container.
        /// </summary>
        [GeneratedCode("Atc.Rest.Api.SourceGenerator", "1.0.0")]
        public static class ServiceCollectionEndpointHandlerExtensions
        {
        }
        """.ReplaceLineEndings("\n");

    [Fact]
    public void ApplyExcludeFromCodeCoverage_FlagFalse_ReturnsContentUnchanged()
    {
        // Act
        var result = GeneratedCodeAttributeHelper.ApplyExcludeFromCodeCoverage(SampleContent, excludeFromCodeCoverage: false);

        // Assert
        Assert.Equal(SampleContent, result);
    }

    [Fact]
    public void ApplyExcludeFromCodeCoverage_NoGeneratedCodeAttribute_ReturnsContentUnchanged()
    {
        // Arrange
        const string content = "namespace Foo;\n\npublic class Bar\n{\n}";

        // Act
        var result = GeneratedCodeAttributeHelper.ApplyExcludeFromCodeCoverage(content, excludeFromCodeCoverage: true);

        // Assert
        Assert.Equal(content, result);
    }

    [Fact]
    public void ApplyExcludeFromCodeCoverage_FlagTrue_InsertsAttributeAfterGeneratedCode()
    {
        // Act
        var result = GeneratedCodeAttributeHelper.ApplyExcludeFromCodeCoverage(SampleContent, excludeFromCodeCoverage: true);

        // Assert
        Assert.Contains(
            "[GeneratedCode(\"Atc.Rest.Api.SourceGenerator\", \"1.0.0\")]\n[ExcludeFromCodeCoverage]\npublic static class ServiceCollectionEndpointHandlerExtensions",
            result,
            StringComparison.Ordinal);
    }

    [Fact]
    public void ApplyExcludeFromCodeCoverage_FlagTrue_AddsRequiredUsing()
    {
        // Act
        var result = GeneratedCodeAttributeHelper.ApplyExcludeFromCodeCoverage(SampleContent, excludeFromCodeCoverage: true);

        // Assert
        Assert.Contains("using System.CodeDom.Compiler;\nusing System.Diagnostics.CodeAnalysis;\n", result, StringComparison.Ordinal);
    }

    [Fact]
    public void ApplyExcludeFromCodeCoverage_WithoutTheCodeDomUsing_AddsTheUsingAfterNullableEnable()
    {
        // Arrange
        var content = SampleContent.Replace("using System.CodeDom.Compiler;\n", string.Empty, StringComparison.Ordinal);

        // Act
        var result = GeneratedCodeAttributeHelper.ApplyExcludeFromCodeCoverage(content, excludeFromCodeCoverage: true);

        // Assert
        Assert.Contains("#nullable enable\nusing System.Diagnostics.CodeAnalysis;\n", result, StringComparison.Ordinal);
        Assert.StartsWith(content[..content.IndexOf("#nullable enable", StringComparison.Ordinal)], result, StringComparison.Ordinal);
    }

    [Fact]
    public void ApplyExcludeFromCodeCoverage_UsingAlreadyPresent_DoesNotDuplicateUsing()
    {
        // Arrange
        var content = SampleContent.Replace(
            "using System.CodeDom.Compiler;",
            "using System.CodeDom.Compiler;\nusing System.Diagnostics.CodeAnalysis;",
            StringComparison.Ordinal);

        // Act
        var result = GeneratedCodeAttributeHelper.ApplyExcludeFromCodeCoverage(content, excludeFromCodeCoverage: true);

        // Assert
        var occurrences = result.Split("using System.Diagnostics.CodeAnalysis;").Length - 1;
        Assert.Equal(1, occurrences);
    }

    [Fact]
    public void ApplyExcludeFromCodeCoverage_MultipleGeneratedCodeAttributes_InsertsAfterEachEligibleDeclaration()
    {
        // Arrange — [ExcludeFromCodeCoverage] is not valid on interfaces, only the class should get it.
        // Normalized to \n regardless of this file's own line endings.
        var content = """
            // <auto-generated />
            #nullable enable

            using System.CodeDom.Compiler;

            namespace Foo;

            [GeneratedCode("Atc.Rest.Api.SourceGenerator", "1.0.0")]
            public interface IFooDefinition
            {
            }

            [GeneratedCode("Atc.Rest.Api.SourceGenerator", "1.0.0")]
            public sealed class FooDefinition : IFooDefinition
            {
            }
            """.ReplaceLineEndings("\n");

        // Act
        var result = GeneratedCodeAttributeHelper.ApplyExcludeFromCodeCoverage(content, excludeFromCodeCoverage: true);

        // Assert
        var occurrences = result.Split("[ExcludeFromCodeCoverage]").Length - 1;
        Assert.Equal(1, occurrences);
        Assert.DoesNotContain(
            "[ExcludeFromCodeCoverage]\npublic interface IFooDefinition",
            result,
            StringComparison.Ordinal);
        Assert.Contains(
            "[ExcludeFromCodeCoverage]\npublic sealed class FooDefinition",
            result,
            StringComparison.Ordinal);
    }

    [Theory]
    [InlineData("public interface IFoo\n{\n}")]
    [InlineData("public enum Foo\n{\n    Bar,\n}")]
    [InlineData("public delegate void Foo();")]
    public void ApplyExcludeFromCodeCoverage_UnsupportedDeclarationKind_DoesNotAddAttributeOrUsing(
        string declaration)
    {
        // Arrange
        var content = $"""
            // <auto-generated />
            #nullable enable

            using System.CodeDom.Compiler;

            namespace Foo;

            [GeneratedCode("Atc.Rest.Api.SourceGenerator", "1.0.0")]
            {declaration}
            """;

        // Act
        var result = GeneratedCodeAttributeHelper.ApplyExcludeFromCodeCoverage(content, excludeFromCodeCoverage: true);

        // Assert
        Assert.Equal(content, result);
        Assert.DoesNotContain("[ExcludeFromCodeCoverage]", result, StringComparison.Ordinal);
        Assert.DoesNotContain("System.Diagnostics.CodeAnalysis", result, StringComparison.Ordinal);
    }

    [Fact]
    public void ApplyExcludeFromCodeCoverage_RecordDeclaration_AddsAttribute()
    {
        // Arrange — normalized to \n regardless of this file's own line endings.
        var content = """
            // <auto-generated />
            #nullable enable

            using System.CodeDom.Compiler;

            namespace Foo;

            [GeneratedCode("Atc.Rest.Api.SourceGenerator", "1.0.0")]
            public record ProblemDetails(
                string? Type,
                string? Title);
            """.ReplaceLineEndings("\n");

        // Act
        var result = GeneratedCodeAttributeHelper.ApplyExcludeFromCodeCoverage(content, excludeFromCodeCoverage: true);

        // Assert
        Assert.Contains(
            "[GeneratedCode(\"Atc.Rest.Api.SourceGenerator\", \"1.0.0\")]\n[ExcludeFromCodeCoverage]\npublic record ProblemDetails(",
            result,
            StringComparison.Ordinal);
    }

    [Fact]
    public void ApplyExcludeFromCodeCoverage_PreservesIndentation()
    {
        // Arrange — normalized to \n regardless of this file's own line endings.
        var content = """
            using System.CodeDom.Compiler;

            namespace Foo
            {
                [GeneratedCode("Atc.Rest.Api.SourceGenerator", "1.0.0")]
                public class Bar
                {
                }
            }
            """.ReplaceLineEndings("\n");

        // Act
        var result = GeneratedCodeAttributeHelper.ApplyExcludeFromCodeCoverage(content, excludeFromCodeCoverage: true);

        // Assert
        Assert.Contains(
            "    [GeneratedCode(\"Atc.Rest.Api.SourceGenerator\", \"1.0.0\")]\n    [ExcludeFromCodeCoverage]\n    public class Bar",
            result,
            StringComparison.Ordinal);
    }

    [Fact]
    public void SuppressMissingXmlComment_InsertsThePragmaAfterNullableEnable()
    {
        var content = "// <auto-generated />\n#nullable enable\n\nnamespace Foo;\n";

        var result = GeneratedCodeAttributeHelper.SuppressMissingXmlComment(content);

        Assert.Equal("// <auto-generated />\n#nullable enable\n#pragma warning disable CS1591\n\nnamespace Foo;\n", result);
    }

    [Fact]
    public void SuppressMissingXmlComment_KeepsTheLineEndingsOfTheFile()
    {
        var content = "// <auto-generated />\r\n#nullable enable\r\n\r\nnamespace Foo;\r\n";

        var result = GeneratedCodeAttributeHelper.SuppressMissingXmlComment(content);

        Assert.Equal("// <auto-generated />\r\n#nullable enable\r\n#pragma warning disable CS1591\r\n\r\nnamespace Foo;\r\n", result);
    }

    [Fact]
    public void SuppressMissingXmlComment_WithoutNullableEnable_InsertsAfterTheAutoGeneratedHeader()
    {
        var content = "// <auto-generated />\nglobal using System;\n";

        var result = GeneratedCodeAttributeHelper.SuppressMissingXmlComment(content);

        Assert.Equal("// <auto-generated />\n#pragma warning disable CS1591\nglobal using System;\n", result);
    }

    [Fact]
    public void SuppressMissingXmlComment_WithoutAHeader_InsertsAtTheTop()
    {
        var result = GeneratedCodeAttributeHelper.SuppressMissingXmlComment("namespace Foo;\n");

        Assert.Equal("#pragma warning disable CS1591\nnamespace Foo;\n", result);
    }

    [Fact]
    public void SuppressMissingXmlComment_IsAppliedOnce()
    {
        var once = GeneratedCodeAttributeHelper.SuppressMissingXmlComment("#nullable enable\nnamespace Foo;\n");

        Assert.Equal(once, GeneratedCodeAttributeHelper.SuppressMissingXmlComment(once));
    }

    [Fact]
    public void SuppressObsolete_InsertsThePragmaAfterNullableEnable_InTheFilesLineEndings()
    {
        var content = "// <auto-generated />\r\n#nullable enable\r\n\r\nnamespace Foo;\r\n";

        var result = GeneratedCodeAttributeHelper.SuppressObsolete(content);

        Assert.Equal("// <auto-generated />\r\n#nullable enable\r\n#pragma warning disable CS0618\r\n\r\nnamespace Foo;\r\n", result);
    }

    [Fact]
    public void SuppressObsolete_WithoutNullableEnable_InsertsAfterTheAutoGeneratedHeader()
    {
        var result = GeneratedCodeAttributeHelper.SuppressObsolete("// <auto-generated />\nglobal using System;\n");

        Assert.Equal("// <auto-generated />\n#pragma warning disable CS0618\nglobal using System;\n", result);
    }

    [Fact]
    public void SuppressObsolete_IsAppliedOnce_AndKeepsTheMissingXmlCommentPragma()
    {
        var once = GeneratedCodeAttributeHelper.SuppressObsolete(
            GeneratedCodeAttributeHelper.SuppressMissingXmlComment("#nullable enable\nnamespace Foo;\n"));

        Assert.Equal(once, GeneratedCodeAttributeHelper.SuppressObsolete(once));
        Assert.Equal(once, GeneratedCodeAttributeHelper.SuppressMissingXmlComment(once));
        Assert.Contains("#pragma warning disable CS1591\n", once, StringComparison.Ordinal);
    }
}